namespace HardwareProfile
{
#ifdef DEVICE_HW_ID
constexpr uint16_t OWN_HW_ID = DEVICE_HW_ID;
#else
constexpr uint16_t OWN_HW_ID = 0; // board header without DEVICE_HW_ID
#endif
constexpr uint32_t OWN_CAPS = (HWP_CAP_BIT_0 << 0) | (HWP_CAP_BIT_1 << 1) | (HWP_CAP_BIT_2 << 2) | (HWP_CAP_BIT_3 << 3) | (HWP_CAP_BIT_4 << 4) | (HWP_CAP_BIT_5 << 5) | (HWP_CAP_BIT_6 << 6) | (HWP_CAP_BIT_7 << 7) | (HWP_CAP_BIT_8 << 8) | (HWP_CAP_BIT_9 << 9) | (HWP_CAP_BIT_10 << 10) | (HWP_CAP_BIT_11 << 11) | (HWP_CAP_BIT_12 << 12) | (HWP_CAP_BIT_13 << 13) | (HWP_CAP_BIT_14 << 14) | (HWP_CAP_BIT_15 << 15);
/// runtime="true" capabilities this board has the place for: only these bits of answerQuery(runtimeCaps) count
constexpr uint32_t RUNTIME_CAPS = (HWP_CAP_BIT_16 << 16);
constexpr uint8_t OWN_VALUES[VALUE_COUNT] = {HWP_VAL_0, HWP_VAL_1, HWP_VAL_2, HWP_VAL_3};
static_assert((HWP_VAL_0) >= 0 && (HWP_VAL_0) <= 255, "value BinaryInputs does not fit one byte");
static_assert((HWP_VAL_1) >= 0 && (HWP_VAL_1) <= 255, "value StatusLeds does not fit one byte");
static_assert((HWP_VAL_2) >= 0 && (HWP_VAL_2) <= 255, "value FlashMB does not fit one byte");
static_assert((HWP_VAL_3) >= 0 && (HWP_VAL_3) <= 255, "value Relays does not fit one byte");

/// @brief Hardware IDs known to the ETS application
constexpr uint16_t KNOWN_HW_IDS[] = {0x1021, 0x1022, 0x1132, 0x1203, 0x1310, 0x1320, 0x2121, 0x2400, 0x3F00, 0x3F01, 0x3F02, 0x3F10, 0x3F11, 0x3F12, 0x3F13, 0x3F14};
constexpr uint16_t KNOWN_HW_ID_COUNT = 16;

constexpr bool isKnown(uint16_t hwId, uint16_t i = 0)
{
    return i < KNOWN_HW_ID_COUNT && (KNOWN_HW_IDS[i] == hwId || isKnown(hwId, i + 1));
}

/// @brief State of the ETS hardware selection against this firmware: read hardware dependent parameters only on Match
enum class Selection : uint8_t
{
    NotSelected, ///< ETS: no hardware selected
    Match,       ///< ETS selection = OWN_HW_ID
    Other,       ///< ETS selection is another board: wrong firmware or wrong selection (optional: log, KO, info LED)
};
static inline Selection checkSelection(uint16_t selected)
{
    return selected == NOT_SELECTED ? Selection::NotSelected : (selected == OWN_HW_ID ? Selection::Match : Selection::Other);
}

/// @brief Device query (ETS button "Hardware vom Geraet abfragen", function property FP_OBJECT_INDEX / FP_PROPERTY_ID):
///        [0] status 0, [1..2] OWN_HW_ID big endian, [3..6] OWN_CAPS | (runtimeCaps & RUNTIME_CAPS) little endian, [7..] OWN_VALUES.
/// @param runtimeCaps bits of the runtime="true" capabilities the firmware found (e.g. a plug-in sensor module), other bits are ignored
/// @return true when objectIndex / propertyId are the device query (answer written), false otherwise.
/// @note In Module::processFunctionProperty: if (HardwareProfile::answerQuery(objectIndex, propertyId, resultData, resultLength)) return true;
static inline bool answerQuery(uint8_t objectIndex, uint8_t propertyId, uint8_t* resultData, uint8_t& resultLength, uint32_t runtimeCaps = 0)
{
    if (objectIndex != FP_OBJECT_INDEX || propertyId != FP_PROPERTY_ID) return false;
    constexpr uint8_t answerLength = 7 + VALUE_COUNT;
    static_assert(answerLength <= 11, "hardware profile answer does not fit a TP standard frame");
    const uint32_t caps = OWN_CAPS | (runtimeCaps & RUNTIME_CAPS);
    resultData[0] = 0;
    resultData[1] = OWN_HW_ID >> 8;
    resultData[2] = OWN_HW_ID & 0xFF;
    resultData[3] = caps & 0xFF;
    resultData[4] = (caps >> 8) & 0xFF;
    resultData[5] = (caps >> 16) & 0xFF;
    resultData[6] = (caps >> 24) & 0xFF;
    for (uint8_t i = 0; i < VALUE_COUNT; i++) resultData[7 + i] = OWN_VALUES[i];
    resultLength = answerLength;
    return true;
}
} // namespace HardwareProfile

// GPIO roles: the per-board parameters of one slot share one byte (ETS union), so any of them
// reads the value of the selected board. Use after knxprod.h. Value 255 = not used.
// ETS writes the byte only while a parameter of the union is visible: read it ONLY when
// ParamHWP_HardwareSelect == OWN_HW_ID and ROLE_<name>_ON_OWN_BOARD; otherwise it holds no value.
namespace HardwareProfile
{
constexpr bool contains(const uint16_t* ids, uint16_t count, uint16_t id, uint16_t i = 0)
{
    return i < count && (ids[i] == id || contains(ids, count, id, i + 1));
}
constexpr uint16_t ROLE_Pin_HW_IDS[] = {0x1021, 0x1022, 0x1310, 0x1320, 0x2121};
constexpr bool ROLE_Pin_ON_OWN_BOARD = contains(ROLE_Pin_HW_IDS, 5, OWN_HW_ID);
} // namespace HardwareProfile
#define HWP_ROLE_Pin_1 ParamHWP_Pin1B3
#define HWP_ROLE_Pin_2 ParamHWP_Pin2B3
